        &lt;!-- Versions of dependent libraries --&gt;
        &lt;logback.version&gt;1.2.10&lt;/logback.version&gt;

    &lt;/properties&gt;

    &lt;dependencies&gt;

        &lt;dependency&gt;
            &lt;groupId&gt;org.odpi.egeria&lt;/groupId&gt;
