            &lt;version&gt;${open-metadata.version}&lt;/version&gt;
        &lt;/dependency&gt;

        &lt;dependency&gt;
            &lt;groupId&gt;org.odpi.egeria&lt;/groupId&gt;
            &lt;artifactId&gt;http-helper&lt;/artifactId&gt;
            &lt;version&gt;${open-metadata.version}&lt;/version&gt;
        &lt;/dependency&gt;

        &lt;dependency&gt;
            &lt;groupId&gt;org.odpi.egeria&lt;/groupId&gt;
            &lt;artifactId&gt;kafka-open-metadata-topic-connector&lt;/artifactId&gt;
            &lt;version&gt;${open-metadata.version}&lt;/version&gt;
        &lt;/dependency&gt;

        &lt;dependency&gt;
            &lt;groupId&gt;org.odpi.egeria&lt;/groupId&gt;
